      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a will of Victorian London', 'author': 'Signature original', 'genre': 'Civil War Tales', 'chapters': [{'n': 1, 'title': 'The Discovery', 'text': "The a will came to Edward Marsh on a rainy Thursday in Victorian London, tucked in a solicitor's envelope smelling of dust and secrets. Edward Marsh was not, by nature, a curious person. Curiosity, in Victorian London, was a luxury for those with full larders.\n\nYet Edward Marsh kept returning to a will, the way one returns to a sore tooth. It told a story — of a debt unpaid, a promise broken, a life ruined. And stories, Edward Marsh was beginning to understand, are a kind of debt themselves.\n\nBy morning Edward Marsh had decided. a will would not stay hidden. Whatever the blackmailer did, whatever Victorian London whispered — courage in every age, and the truth would have its day."}, {'n': 2, 'title': 'Inquiries', 'text': "the blackmailer noticed. A carriage followed Edward Marsh home. A note arrived: 'Some things are better left buried.' Edward Marsh burned the note and kept digging. Buried things, Edward Marsh had learned, have a way of surfacing.\n\nEdward Marsh began carefully, as one must in Victorian London: a question to the vicar, a look at the parish register, a conversation with the old soldier who remembered everything and forgave nothing.\n\nthe vicar's son proved unexpectedly brave, carrying messages, watching doors, learning the servants' gossip that the masters never hear. 'The downstairs knows everything,' the vicar's son said. 'Upstairs just pays for it.'"}, {'n': 3, 'title': 'The Witness', 'text': "Edward Marsh promised protection — a promise that felt like a stone in the pocket, heavy and necessary. the vicar's son arranged the safe room, the food, the watchers. Victorian London's poor take care of their own; they always have.\n\nEdward Marsh wrote it all down, every thread, every name, and sealed it three ways. If the blackmailer silenced them, the story would still speak. courage in every age — even in Victorian London, even then.\n\nThe witness lived in Victorian London's poorest court, old and afraid and tired of being afraid. a will in Edward Marsh's hands loosened their tongue: yes, they had seen. Yes, they would swear. No, they had never dared."}, {'n': 4, 'title': 'The Reckoning', 'text': "the blackmailer was taken — quietly, for the family's sake, but taken. The mill was sold. The debts were paid. The witness wept with relief, and the vicar's son's bruises became badges.\n\nThe magistrate squirmed. The crowd — Victorian London's people, mill hands and merchants' wives — began to murmur, and the murmur became a voice. the blackmailer's money couldn't buy this room. Not tonight.\n\nIt came to a head at the assembly rooms, in front of all Victorian London: Edward Marsh stood and spoke, with a will held high and the witness beside them. The gaslight seemed to lean in to listen."}, {'n': 5, 'title': 'Restoration', 'text': "the vicar's son married the vicar's son — or daughter; Victorian London gossiped happily either way — and named their first child after Edward Marsh, who pretended to mind and didn't.\n\ncourage in every age — Edward Marsh had it carved, finally, on no monument at all, just lived it, in Victorian London, in every ordinary, extraordinary day.\n\nVictorian London changed, the way places do when a bad tooth is pulled: slowly, then all at once. The mill got new owners. The court got a new magistrate. a will got a place of honor — and then, deliberately, a quiet drawer."}, {'n': 6, 'title': 'Coda: The Drawer', 'text': "the blackmailer is a name in the records, a caution. Victorian London is a place where the mills run fair and the magistrate is honest, mostly, which is as much as any age can ask.\n\nThe gaslight is electric now. The carriages are cars. But a will is still a will, and Edward Marsh is still Edward Marsh, and the drawer still opens.\n\na will rests now in Edward Marsh's drawer, among the bills and the birthday cards. Sometimes Edward Marsh takes it out, just to hold the weight of it: proof that one person, in Victorian London, in any age, can tip the scales."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

